import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.Ck6QqhZl.js";const f=JSON.parse('{"title":"Getting Started - Soundef Forge","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started.md","filePath":"docs/getting-started.md"}'),r={name:"docs/getting-started.md"};function s(n,e,i,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="getting-started-soundef-forge" tabindex="-1">Getting Started - Soundef Forge <a class="header-anchor" href="#getting-started-soundef-forge" aria-label="Permalink to &quot;Getting Started - Soundef Forge&quot;">​</a></h1><blockquote><p>See the <a href="./spec">Spec</a> for the file reference and the home page for the pitch.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Forge runs offline on Windows, macOS, Linux. No library to install. A project is any folder that holds <code>sounds/</code> and <code>soundefs/</code> side by side (for example <code>MyProject/</code>).</p><h2 id="open-a-project" tabindex="-1">Open a Project <a class="header-anchor" href="#open-a-project" aria-label="Permalink to &quot;Open a Project&quot;">​</a></h2><ol><li>Select <code>File → Open Project…</code>.</li><li>Choose your project folder (any name, for example <code>MyProject/</code>). It must contain <code>sounds/</code> and <code>soundefs/</code> folders.</li><li>Forge checks the folder and watches for file changes.</li></ol><p>Right tabs:</p><ul><li><code>Soundefs</code> - list of your <code>.soundef</code> files. Select a file to edit.</li><li><code>Sounds</code> - sound palette. Search by name, listen, and insert into layers.</li></ul><h2 id="edit-and-preview" tabindex="-1">Edit and Preview <a class="header-anchor" href="#edit-and-preview" aria-label="Permalink to &quot;Edit and Preview&quot;">​</a></h2><ol><li>Select a file in the <code>Soundefs</code> tab. The editor shows the file. The TransportBar shows <code>Play</code>, <code>Random</code>, <code>Stop</code>, and <code>seed</code>.</li><li>A dot shows unsaved changes. There is no auto-save.</li><li>Edit the text or use the TransportBar. <code>Play</code> previews the sound. <code>seed</code> changes the variation. The same seed always gives the same result.</li><li>Select <code>Save</code> (<code>Cmd+S</code> / <code>Ctrl+S</code>) to write the file. Preview uses the editor content, not the saved file.</li><li>If the file changes on disk and the editor is clean, Forge reloads it. If the editor has unsaved changes, Forge shows a banner. Select <code>Load</code> to use the disk file or <code>Keep mine</code> to keep your edits.</li></ol><h2 id="sounds-palette-and-insert" tabindex="-1">Sounds Palette and Insert <a class="header-anchor" href="#sounds-palette-and-insert" aria-label="Permalink to &quot;Sounds Palette and Insert&quot;">​</a></h2><ul><li>In the <code>Sounds</code> tab, select <code>audition</code> to listen to a file.</li><li>Select <code>Insert</code> to add the file to the selected layer. Paths are relative to <code>sounds/</code>. Example: <code>swords/body_01.wav</code> refers to <code>MyProject/sounds/swords/body_01.wav</code> (your project folder). Do not use absolute paths or <code>../</code>.</li></ul><h2 id="timeline-and-waveform" tabindex="-1">Timeline and Waveform <a class="header-anchor" href="#timeline-and-waveform" aria-label="Permalink to &quot;Timeline and Waveform&quot;">​</a></h2><ul><li><strong>Behavior timeline</strong> - one lane for each layer. The lane order matches the file order. A dashed lane means the layer did not play on this trigger.</li><li>Drag a lane to change its offset. This updates the file and marks it as unsaved. Save to keep the change. Select a lane to highlight its <code>sources</code> in the editor.</li><li><strong>Final waveform</strong> - the mixed result. A red dot means the result is too loud. Lower <code>gain</code> if you see the red dot.</li></ul><p>Actions: <code>Bake</code>, <code>Download</code>, <code>Normalize -1dB</code>, and <code>Baked A/B</code>.</p><h2 id="bake-download-and-share" tabindex="-1">Bake, Download, and Share <a class="header-anchor" href="#bake-download-and-share" aria-label="Permalink to &quot;Bake, Download, and Share&quot;">​</a></h2><ul><li><strong>Bake</strong> - renders the selected <code>.soundef</code> plus current <code>seed</code> to <code>baked/&lt;name&gt;_baked_&lt;seed&gt;.wav</code> in <code>&lt;project&gt;/baked/</code> (for example <code>MyProject/baked/</code>). Use it for A/B against live preview.</li><li><strong>Download</strong> - saves the baked wav outside the project.</li><li><strong>Normalize -1dB</strong> - lowers the baked buffer to clear a red clip dot.</li><li><strong>Baked A/B</strong> - quick compare of live vs last bake.</li><li><strong>includes json plan</strong> - when checked, Bake also writes <code>baked/&lt;name&gt;_&lt;seed&gt;.plan.json</code> validated at <code>/schemas/playback-plan.v0.json</code>. Ship that JSON if you want to play without reimplementing resolve.</li><li><strong>Share</strong> - use <code>Export Pack</code> and <code>Import Pack</code> to share soundefs and sounds. Export checks paths. Import checks the pack version.</li></ul><h2 id="if-open-project-shows-no-files" tabindex="-1">If Open Project shows no files <a class="header-anchor" href="#if-open-project-shows-no-files" aria-label="Permalink to &quot;If Open Project shows no files&quot;">​</a></h2><ul><li>Open the parent project folder that holds both <code>sounds/</code> and <code>soundefs/</code> - not one of them alone. Names are lowercase.</li><li>If the Soundefs tab is empty, go up one level and pick again.</li><li>Watcher uses 120ms debounce and only runs with a valid project open.</li></ul><h2 id="project-favorites" tabindex="-1">Project Favorites <a class="header-anchor" href="#project-favorites" aria-label="Permalink to &quot;Project Favorites&quot;">​</a></h2><p>Forge remembers recent projects and starred files on this computer.</p>',21)])])}const p=o(r,[["render",s]]);export{f as __pageData,p as default};
